import React from 'react';
import { useNavigate } from 'react-router-dom';
import FranchiseList from './FranchiseList';
import { logout } from '../services/api';
import { Button, Container, Box, Typography, Grid, Paper } from '@mui/material';

const Dashboard = () => {
  const navigate = useNavigate();

  const handleLogout = async () => {
    try {
      await logout(navigate);
      localStorage.removeItem('token');
      navigate('/login');
    } catch (error) {
      console.error('Logout failed:', error);
      alert('There was an error logging out. Please try again.');
    }
  };

  return (
    <Container maxWidth="lg" sx={{ mt: 4 }}>
      <Paper elevation={4} sx={{ p: 4, mb: 4 }}>
        <Typography variant="h2" align="center" gutterBottom>
          Welcome To Superadmin Dashboard
        </Typography>
        <Grid container spacing={2} justifyContent="center" sx={{ mb: 4 }}>
          <Grid item>
            <Button
              variant="contained"
              color="primary"
              onClick={() => navigate('/create-superadmin')}
            >
              Create User
            </Button>
          </Grid>
          <Grid item>
            <Button
              variant="contained"
              color="secondary"
              onClick={() => navigate('/create-franchise')}
            >
              Create Franchise
            </Button>
          </Grid>
          <Grid item>
            <Button
              variant="contained"
              color="info"
              onClick={() => navigate('/exam-data')}
            >
              Manage Exam Data
            </Button>
          </Grid>
          <Grid item>
            <Button
              variant="contained"
              color="error"
              onClick={handleLogout}
            >
              Logout
            </Button>
          </Grid>
        </Grid>
      </Paper>

      <Paper elevation={3} sx={{ p: 3 }}>
        <Typography variant="h5" align="center" gutterBottom>
          Franchise List
        </Typography>
        <FranchiseList />
      </Paper>
    </Container>
  );
};

export default Dashboard;
